#!/usr/bin/env python3
import json, os, plistlib, re, sys
from pathlib import Path

p = Path("pubspec.yaml")
if p.exists(): p.write_text(re.sub(r"^version:\s*1\.\d+\.\d+\+?\d*", "version: 1.3.1+15", p.read_text("utf-8"), flags=re.M), "utf-8")

p = Path("assets/sounds/boot_unused.mp3")
