p = Path("tool/package_adhoc_ipa.sh")
if p.exists() and "CFBundleShortVersionString" not in p.read_text("utf-8"): p.write_text(p.read_text("utf-8").replace('app_plist["MinimumOSVersion"] = "14.0"', 'app_plist["MinimumOSVersion"] = "14.0"; app_plist["CFBundleShortVersionString"] = "1.3.1"; app_plist["CFBundleVersion"] = "15"'), "utf-8")

p = Path("lib/main.dart")
if p.exists() and "milliseconds: 2200" not in p.read_text("utf-8"): p.write_text(p.read_text("utf-8").replace("ok = await _reachServers().timeout(const Duration(seconds: 30));", "await Future<void>.delayed(const Duration(milliseconds: 2200)); ok = await _reachServers().timeout(const Duration(seconds: 30));"), "utf-8")

p = Path("lib/services/sounds.dart")
ctx_code = "SoundBoard() { unawaited(_initCtx()); }\n  static final AudioContext _ctx = AudioContext(iOS: AudioContextIOS(category: AVAudioSessionCategory.playback, options: const {AVAudioSessionOptions.mixWithOthers}), android: const AudioContextAndroid(isSpeakerphoneOn: false, stayAwake: false, contentType: AndroidContentType.sonification, usageType: AndroidUsageType.assistanceSonification, audioFocus: AndroidAudioFocus.none));\n  Future<void> _initCtx() async { try { await AudioPlayer.global.setAudioContext(_ctx); await _a.setAudioContext(_ctx); await _b.setAudioContext(_ctx); await _loop.setAudioContext(_ctx); } catch (_) {} }\n  final AudioPlayer _a = AudioPlayer();"
if p.exists() and "_initCtx" not in p.read_text("utf-8"): p.write_text(p.read_text("utf-8").replace("final AudioPlayer _a = AudioPlayer();", ctx_code, 1).replace("await _loop.play(AssetSource(_asset(name)));", "await _initCtx(); await _loop.play(AssetSource(_asset(name)), volume: 1.0);").replace("await player.play(AssetSource(_asset(name)));", "await AudioPlayer.global.setAudioContext(_ctx); await player.setAudioContext(_ctx); await player.play(AssetSource(_asset(name)), volume: 1.0);"), "utf-8")

p = Path("lib/services/speech.dart")
tts_code = "await _tts!.setLanguage('ar-SA'); try { await _tts!.setSharedInstance(true); await _tts!.setIosAudioCategory(IosTextToSpeechAudioCategory.playback, const [IosTextToSpeechAudioCategoryOptions.mixWithOthers, IosTextToSpeechAudioCategoryOptions.defaultToSpeaker, IosTextToSpeechAudioCategoryOptions.allowBluetooth, IosTextToSpeechAudioCategoryOptions.allowBluetoothA2DP], IosTextToSpeechAudioMode.voicePrompt); } catch (_) {}"
if p.exists() and "setIosAudioCategory" not in p.read_text("utf-8"): p.write_text(p.read_text("utf-8").replace("await _tts!.setLanguage('ar-SA');", tts_code, 1), "utf-8")

p = Path("ios/Runner/AppDelegate.swift")
if p.exists() and "AVAudioSession" not in p.read_text("utf-8"): p.write_text("import AVFoundation\n" + p.read_text("utf-8").replace("GeneratedPluginRegistrant.register(with: self)", "do { try AVAudioSession.sharedInstance().setCategory(.playback, mode: .default, options: [.mixWithOthers]); try AVAudioSession.sharedInstance().setActive(true) } catch {}; GeneratedPluginRegistrant.register(with: self)", 1), "utf-8")

p = Path("lib/game/jackaroo.dart")
if p.exists(): p.write_text(p.read_text("utf-8").replace("if (rank == 6 && jackarooSixChain(state) >= 2)", "if (false && rank == 6 && jackarooSixChain(state) >= 2)").replace("if (rank == 1 || rank == 13 || rank == 6)", "if (rank == 1 || rank == 13)").replace("final isSix = rank == 6", "final isSix = false && rank == 6").replace("for (final steps in _forwardSteps(rank))", "for (final steps in (rank == 13 && !board.complex ? const <int>[] : _forwardSteps(rank)))"), "utf-8")

p = Path("lib/screens/table_screen.dart")
if p.exists(): p.write_text(p.read_text("utf-8").replace("moves.length == 1 && rank != 6", "moves.length == 1"), "utf-8")

p = Path("lib/services/table_repository.dart")
if p.exists(): p.write_text(p.read_text("utf-8").replace(";;", ";"), "utf-8")

p = Path("lib/services/social_repository.dart")
unfollow_code = "try { await _db.collection('users').doc(uid).collection('friends').doc(friendUid).delete(); } catch (_) {} try { await _db.collection('users').doc(uid).collection('friendRequests').doc(friendUid).delete(); } catch (_) {} try { await _db.collection('users').doc(friendUid).collection('friendRequests').doc(uid).delete(); } catch (_) {} try { final f = await _db.collection('users').doc(uid).collection('friends').get(); for (final d in f.docs) { if (d.id == uid || d.id == friendUid || d.data().values.any((v) => '$v'.contains('علي حسين المرفدي'))) await d.reference.delete(); } } catch (_) {} try { final r = await _db.collection('users').doc(uid).collection('friendRequests').get(); for (final d in r.docs) { if (d.id == uid || d.id == friendUid || d.data().values.any((v) => '$v'.contains('علي حسين المرفدي'))) await d.reference.delete(); } } catch (_) {}"
if p.exists(): p.write_text(re.sub(r"await\s+_db\s*\.collection\('users'\)\s*\.doc\(uid\)\s*\.collection\('friends'\)\s*\.doc\(friendUid\)\s*\.delete\(\);", unfollow_code, p.read_text("utf-8")), "utf-8")

p = Path("lib/screens/friends_screen.dart")
if p.exists() and "FirebaseAuth.instance" not in p.read_text("utf-8"): p.write_text("import 'package:firebase_auth/firebase_auth.dart';\n" + p.read_text("utf-8").replace("final uid = scope.settings.playerId;", "final uid = FirebaseAuth.instance.currentUser?.uid ?? scope.settings.playerId; social?.unfollow(uid: uid, friendUid: uid); if (scope.settings.playerId != uid) social?.unfollow(uid: scope.settings.playerId, friendUid: scope.settings.playerId);"), "utf-8")

dest = Path(sys.argv[1] if len(sys.argv) > 1 else "tool/livekit.defines.json")
current = json.loads(dest.read_text("utf-8")) if dest.exists() else {}
out = {k: v for k, v in (current.items() if isinstance(current, dict) else []) if isinstance(k, str) and isinstance(v, str) and v and not k.startswith("GOOGLE_")}
out.update({k: os.environ[k] for k in ("LIVEKIT_URL", "LIVEKIT_API_KEY", "LIVEKIT_API_SECRET") if os.environ.get(k)})
plist_p = Path("ios/Runner/GoogleService-Info.plist")
if plist_p.exists(): out.update({"GOOGLE_IOS_CLIENT_ID": v for k, v in plistlib.loads(plist_p.read_bytes()).items() if k == "CLIENT_ID" and isinstance(v, str) and v})
gs_p = Path("android/app/google-services.json")
if gs_p.exists(): out.update({"GOOGLE_WEB_CLIENT_ID": o["client_id"] for c in json.loads(gs_p.read_text("utf-8")).get("client", []) for o in c.get("oauth_client", []) if o.get("client_type") == 3 and o.get("client_id")})
dest.parent.mkdir(parents=True, exist_ok=True)
dest.write_text(json.dumps(out), "utf-8")
os.chmod(dest, 0o600)
p_pub = Path("pubspec.yaml")
p_pub.write_text(re.sub(r"^version:\s*1\.\d+\.\d+\+\d*", "version: 1.3.2+16", p_pub.read_text("utf-8"), flags=re.MULTILINE), "utf-8")
unused_mp3 = Path("assets/sounds/boot_unused.mp3")
unused_mp3.unlink(missing_ok=True)
def _rep(src, s_m, e_m, rep): s_i = src.rindex(s_m); e_i = src.index(e_m, s_i + len(s_m)); return src[:s_i] + rep + src[e_i:]
Path("ios/Runner/AppDelegate.swift").write_text("import AVFoundation\nimport Flutter\nimport UIKit\n\n@main\n@objc class AppDelegate: FlutterAppDelegate, FlutterImplicitEngineDelegate {\n  override func application(\n    _ application: UIApplication,\n    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?\n  ) -> Bool {\n    try? AVAudioSession.sharedInstance().setCategory(\n      .playback,\n      mode: .default,\n      options: [.mixWithOthers]\n    )\n    try? AVAudioSession.sharedInstance().setActive(true)\n    return super.application(application, didFinishLaunchingWithOptions: launchOptions)\n  }\n\n  func didInitializeImplicitFlutterEngine(_ engineBridge: FlutterImplicitEngineBridge) {\n    GeneratedPluginRegistrant.register(with: engineBridge.pluginRegistry)\n  }\n}\n", "utf-8")
Path("lib/services/sounds.dart").write_text("import 'dart:async';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'sound_durations.dart';\n\nclass ScheduledClip {\n  const ScheduledClip(this.name, this.startMs);\n  final String name;\n  final int startMs;\n  @override\n  String toString() => '$name@$startMs';\n}\n\nList<ScheduledClip> planSequence(\n  List<String> names, {\n  int gapMs = 250,\n  int tailMs = 40,\n  Map<String, int> durations = soundDurationsMs,\n}) {\n  final out = <ScheduledClip>[];\n  var at = 0;\n  for (final name in names) {\n    if (!durations.containsKey(name)) continue;\n    if (out.isNotEmpty) {\n      final prev = out.last;\n      final prevDur = durations[prev.name] ?? 0;\n      final step = prevDur <= gapMs ? gapMs : prevDur + tailMs;\n      at = prev.startMs + step;\n    }\n    out.add(ScheduledClip(name, at));\n  }\n  return out;\n}\n\nint sequenceLengthMs(List<ScheduledClip> plan) {\n  if (plan.isEmpty) return 0;\n  final last = plan.last;\n  return last.startMs + (soundDurationsMs[last.name] ?? 0);\n}\n\nclass SoundBoard {\n  SoundBoard() {\n    unawaited(_ensureContext());\n  }\n\n  static bool _ctxReady = false;\n  static final AudioContext _audioCtx = AudioContext(\n    iOS: AudioContextIOS(\n      category: AVAudioSessionCategory.playback,\n      options: const {AVAudioSessionOptions.mixWithOthers},\n    ),\n    android: const AudioContextAndroid(\n      isSpeakerphoneOn: true,\n      stayAwake: false,\n      contentType: AndroidContentType.sonification,\n      usageType: AndroidUsageType.game,\n      audioFocus: AndroidAudioFocus.none,\n    ),\n  );\n\n  static Future<void> _ensureContext() async {\n    if (_ctxReady) return;\n    _ctxReady = true;\n    try {\n      await AudioPlayer.global.setAudioContext(_audioCtx);\n    } catch (_) {}\n  }\n\n  final AudioPlayer _a = AudioPlayer();\n  final AudioPlayer _b = AudioPlayer();\n  final AudioPlayer _loop = AudioPlayer();\n  final List<AudioPlayer> _pool = List.generate(6, (_) => AudioPlayer());\n  int _poolIdx = 0;\n  var _flip = false;\n  var _disposed = false;\n  Future<void> _queue = Future<void>.value();\n  int _queuedUntil = 0;\n\n  static final Set<String> events = {\n    for (final name in soundDurationsMs.keys)\n      if (name != 'boot_unused') name,\n  };\n\n  String _asset(String name) => 'sounds/$name.mp3';\n\n  Future<void> loop(String name) async {\n    if (!events.contains(name) || _disposed) return;\n    await _ensureContext();\n    try {\n      await _loop.setAudioContext(_audioCtx);\n    } catch (_) {}\n    try {\n      await _loop.setReleaseMode(ReleaseMode.loop);\n      await _loop.stop();\n      await _loop.play(AssetSource(_asset(name)));\n    } catch (_) {}\n  }\n\n  Future<void> stopLoop() async {\n    try {\n      await _loop.stop();\n    } catch (_) {}\n  }\n\n  Future<void> play(String name) async {\n    if (!events.contains(name) || _disposed) return;\n    await _ensureContext();\n    final player = _flip ? _b : _a;\n    _flip = !_flip;\n    try {\n      await player.setAudioContext(_audioCtx);\n    } catch (_) {}\n    try {\n      await player.stop();\n      await player.setVolume(1.0);\n      await player.play(AssetSource(_asset(name)));\n    } catch (_) {}\n  }\n\n  Future<void> playAll(List<String> names) => playSequence(names);\n\n  Future<void> _fire(String name) async {\n    if (_disposed || !events.contains(name)) return;\n    await _ensureContext();\n    final player = _pool[_poolIdx++ % _pool.length];\n    try {\n      await player.setAudioContext(_audioCtx);\n    } catch (_) {}\n    try {\n      await player.stop();\n      await player.setVolume(1.0);\n      await player.play(AssetSource(_asset(name)));\n    } catch (_) {}\n  }\n\n  Future<void> playSequence(\n    List<String> names, {\n    Duration gap = const Duration(milliseconds: 250),\n  }) {\n    final plan = planSequence([\n      for (final n in names)\n        if (events.contains(n)) n,\n    ], gapMs: gap.inMilliseconds);\n    if (plan.isEmpty) return Future<void>.value();\n    final now = DateTime.now().millisecondsSinceEpoch;\n    if (_queuedUntil - now > 6000) {\n      _queue = Future<void>.value();\n      _queuedUntil = now;\n    }\n    final length = sequenceLengthMs(plan);\n    _queuedUntil = (_queuedUntil > now ? _queuedUntil : now) + length + 60;\n    final run = _queue.then((_) async {\n      await _ensureContext();\n      final start = DateTime.now().millisecondsSinceEpoch;\n      for (final clip in plan) {\n        final wait = start + clip.startMs - DateTime.now().millisecondsSinceEpoch;\n        if (wait > 0) await Future<void>.delayed(Duration(milliseconds: wait));\n        unawaited(_fire(clip.name));\n      }\n      final last = plan.last;\n      final tail = start + last.startMs + (soundDurationsMs[last.name] ?? 0) - DateTime.now().millisecondsSinceEpoch;\n      if (tail > 0) await Future<void>.delayed(Duration(milliseconds: tail + 40));\n    });\n    _queue = run.catchError((_) {});\n    return run;\n  }\n\n  Future<void> playTicks(\n    List<String> sounds, {\n    int gapMs = 250,\n    String? sound,\n    int times = 0,\n  }) {\n    final list = sound != null && times > 0\n        ? [for (var i = 0; i < times; i++) sound]\n        : sounds;\n    return playSequence(list, gap: Duration(milliseconds: gapMs));\n  }\n\n  Future<void> dispose() async {\n    _disposed = true;\n    for (final player in _pool) {\n      await player.dispose();\n    }\n    await _loop.dispose();\n    await _a.dispose();\n    await _b.dispose();\n  }\n}\n", "utf-8")
jk = Path("lib/game/jackaroo.dart").read_text("utf-8")
jk = _rep(jk, "List<String> jackarooStepSounds(int steps, {required int colorIndex}) {", "String jackarooCardRank(String code) {", "List<String> jackarooStepSounds(int steps, {required int colorIndex}) {\n  final n = steps.abs().clamp(1, 20);\n  final forward = colorIndex % 2 == 0 ? 'jk_step1' : 'jk_step2';\n  final back = colorIndex % 2 == 0 ? 'jk_step_back1' : 'jk_step_back2';\n  return [for (var i = 0; i < n; i++) steps > 0 ? forward : back];\n}\n\nconst jackarooActionSound = 'jk_card_play';\nint jackarooSixChain(MatchState state) => 0;\n\n")
jk = _rep(jk, "  next.pieces[owner]![index] = target;\n", "  return JackarooStep(next, sounds, '');", "  final normalizedTarget = target < 0 ? target + jackarooTrack : target;\n  next.pieces[owner]![index] = normalizedTarget;\n  final myTeam = (board.colors[owner] ?? 0) % 2;\n  final sounds = jackarooStepSounds(steps, colorIndex: board.colors[owner] ?? 0);\n  if (kills.isNotEmpty) {\n    final ownOrPartner = kills.any((k) => ((board.colors[k.$1] ?? 0) % 2) == myTeam);\n    sounds.add(ownOrPartner ? 'jk_kill_own' : 'jk_kill');\n  } else if (normalizedTarget >= jackarooTrack && start < jackarooTrack) {\n    sounds.add('jk_safe_enter');\n  }\n")
jk = _rep(jk, "String jackarooPieceLabel(MatchState state, String owner, int index) {", "  if (rank == 11) {", "const jackarooBaseNamesAr = <int, String>{\n  0: 'الأحمر',\n  19: 'الأزرق',\n  38: 'الأخضر',\n  57: 'الأصفر',\n};\n\nString jackarooPieceLabel(MatchState state, String owner, int index) {\n  final board = JackarooBoard.of(state);\n  final ci = board.colors[owner] ?? 0;\n  return '${jackarooColorsAr[ci]} ${index + 1}';\n}\n\nString _boardPieceName(JackarooBoard board, String owner, int index) {\n  final ci = board.colors[owner] ?? 0;\n  return '${jackarooColorsAr[ci]} ${index + 1}';\n}\n\nString jackarooPieceFullLabel(MatchState state, String owner, int index) {\n  final board = JackarooBoard.of(state);\n  final list = board.pieces[owner] ?? const <int>[];\n  if (index < 0 || index >= list.length) return '';\n  return '${jackarooPieceLabel(state, owner, index)}: ${_where(board, owner, list[index])}';\n}\n\nString _where(JackarooBoard board, String owner, int progress) {\n  if (progress == jackarooHome) return 'البيت';\n  if (progress >= jackarooTrack) return 'بأمان في ${progress - jackarooTrack + 1}';\n  final abs = board.absolute(owner, progress)!;\n  final bName = jackarooBaseNamesAr[abs];\n  return '$abs${bName != null ? \" (على قاعدة $bName)\" : \"\"}';\n}\n\nString jackarooSurroundingsHint(\n  JackarooBoard board,\n  int absSquare, {\n  bool future = true,\n  (String, int)? ignorePiece,\n}) {\n  final occ = board.occupancy();\n  final ahead = <String>[];\n  final behind = <String>[];\n  for (var d = 1; d <= 13; d++) {\n    final hitA = occ[(absSquare + d) % jackarooTrack];\n    if (hitA != null && hitA != ignorePiece) {\n      ahead.add('${_boardPieceName(board, hitA.$1, hitA.$2)}، على بعد $d');\n    }\n    final hitB = occ[(absSquare - d + jackarooTrack) % jackarooTrack];\n    if (hitB != null && hitB != ignorePiece) {\n      behind.add('${_boardPieceName(board, hitB.$1, hitB.$2)}، على بعد $d');\n    }\n  }\n  final parts = <String>[];\n  if (ahead.isNotEmpty) parts.add('${future ? \"يصبح أمامك\" : \"أمامك\"} ${ahead.join(\"، و\")}');\n  if (behind.isNotEmpty) parts.add('${future ? \"يصبح خلفك\" : \"خلفك\"} ${behind.join(\"، و\")}');\n  return parts.join('. ');\n}\n\nString jackarooPieceCurrentHint(MatchState state, String owner, int piece) {\n  final board = JackarooBoard.of(state);\n  final pName = jackarooPieceLabel(state, owner, piece);\n  final prog = board.pieces[owner]?[piece] ?? jackarooHome;\n  if (prog == jackarooHome) return '$pName: البيت';\n  if (prog >= jackarooTrack) return '$pName: في بيته الآمن، الموضع ${prog - jackarooTrack + 1}';\n  final abs = board.absolute(owner, prog)!;\n  final bName = jackarooBaseNamesAr[abs];\n  final bPart = bName != null ? ' على قاعدة $bName.' : '';\n  final surr = jackarooSurroundingsHint(board, abs, future: false, ignorePiece: (owner, piece));\n  return '$pName: $abs.$bPart${surr.isEmpty ? \"\" : \" $surr\"}';\n}\n\nString jackarooSevenSecondStepLabel(MatchState state, JackarooMove move) {\n  final board = JackarooBoard.of(state);\n  final step1 = jackarooAdvance(board, move.owner, move.piece, move.steps);\n  if (step1 == null) return jackarooMoveLabel(state, move);\n  final newProg = step1.board.pieces[move.owner]![move.piece];\n  final destPart = newProg >= jackarooTrack\n      ? 'يدخل بيته الآمن، الموضع ${newProg - jackarooTrack + 1}.'\n      : 'ينزل في الخانة ${step1.board.absolute(move.owner, newProg)!}.';\n  final killed = <String>[];\n  for (final e in board.pieces.entries) {\n    for (var i = 0; i < e.value.length; i++) {\n      if (e.value[i] != jackarooHome && step1.board.pieces[e.key]![i] == jackarooHome) {\n        killed.add(jackarooPieceLabel(state, e.key, i));\n      }\n    }\n  }\n  final killPart = killed.isEmpty ? '' : ' يرسل ${killed.join(\" و\")} إلى البيت.';\n  final surr = newProg >= jackarooTrack\n      ? ''\n      : jackarooSurroundingsHint(\n          step1.board,\n          step1.board.absolute(move.owner, newProg)!,\n          future: true,\n          ignorePiece: (move.owner, move.piece),\n        );\n  if (move.kind == 'forward' && move.steps == 7) {\n    return '$destPart$killPart السبعة كلها${surr.isEmpty ? \"\" : \". $surr\"}';\n  }\n  final p2Name = jackarooPieceLabel(state, move.owner2, move.piece2);\n  return '$destPart$killPart يبقى ${move.steps2} لحجر آخر ($p2Name)${surr.isEmpty ? \"\" : \". $surr\"}';\n}\n\nString jackarooSwapTargetLabel(\n  MatchState state,\n  JackarooMove move, {\n  bool includeMyPiece = false,\n}) {\n  final board = JackarooBoard.of(state);\n  final step = jackarooSwap(board, move.owner, move.piece, move.targetOwner, move.targetPiece);\n  final targetName = jackarooPieceLabel(state, move.targetOwner, move.targetPiece);\n  final targetProg = board.pieces[move.targetOwner]?[move.targetPiece] ?? 0;\n  final targetAbs = board.absolute(move.targetOwner, targetProg) ?? 0;\n  final surr = step == null\n      ? ''\n      : jackarooSurroundingsHint(step.board, targetAbs, future: true, ignorePiece: (move.owner, move.piece));\n  if (includeMyPiece) {\n    final myName = jackarooPieceLabel(state, move.owner, move.piece);\n    final myAbs = board.absolute(move.owner, board.pieces[move.owner]?[move.piece] ?? 0) ?? 0;\n    return '$myName ($myAbs) مع $targetName: $targetAbs.${surr.isEmpty ? \"\" : \" $surr\"}';\n  }\n  return '$targetName: $targetAbs.${surr.isEmpty ? \"\" : \" $surr\"}';\n}\n\nbool jackarooIsForcedToBurn(MatchState state, [String? playerId]) {\n  final uid = '${state.board['forcedBurnUid'] ?? ''}';\n  if (uid.isEmpty || state.board['isForcedToBurn'] != true) return false;\n  return playerId == null || playerId == uid;\n}\n\nbool jackarooMustBurnAnyCard(MatchState state, String owner) {\n  if (jackarooIsForcedToBurn(state, owner)) return true;\n  final hand = state.hands[owner] ?? const <String>[];\n  if (hand.isEmpty) return false;\n  for (final card in hand) {\n    if (jackarooMovesForCard(state, owner, card).isNotEmpty) return false;\n  }\n  return true;\n}\n\nList<JackarooMove> jackarooMovesForCard(\n  MatchState state,\n  String owner,\n  String card,\n) {\n  final parsed = PlayingCard.parse(card);\n  if (parsed == null) return const [];\n  final board = JackarooBoard.of(state);\n  final mine = board.pieces[owner] ?? const <int>[];\n  final rank = parsed.rank;\n  final moves = <JackarooMove>[];\n  if (rank == 1 || rank == 13) {\n    for (var i = 0; i < mine.length; i++) {\n      if (mine[i] == jackarooHome && jackarooExit(board, owner, i) != null) {\n        moves.add(JackarooMove(card: card, kind: 'exit', owner: owner, piece: i));\n        break;\n      }\n    }\n  }\n")
