ts = ts.replace("labelOverride: forceBurn ? 'حرق ${card.arabicName}' : null,", "labelOverride: forceBurn ? 'حرق ${_scope.settings.nameCards ? card.arabicName : card.englishName}' : null,")
ts = _rep(ts, "        if (!colored)\n", "        if (last != null)\n", "        if (colored && phase == 'move' && _myTurn() && legal.isNotEmpty)\n          Wrap(\n            alignment: WrapAlignment.center,\n            spacing: 4,\n            runSpacing: 4,\n            children: [\n              for (final opt in legal)\n                GameNode(\n                  label: ludoPieceLabel(state, me, opt.piece),\n                  selected: selected == opt.piece,\n                  onTap: () => _selectLudoPiece(state, me, opt.piece, legal),\n                  child: _pieceChip(\n                    ludoPieceLabel(state, me, opt.piece),\n                    selected: selected == opt.piece,\n                  ),\n                ),\n            ],\n          ),\n")
Path("lib/screens/table_screen.dart").write_text(ts, "utf-8")
